409: func (c *greenhouseContract) requireRecorded(t *testing.T, result map[string]any, head, verdict string, blocking int) {
410: 	t.Helper()
411: 	if result["outcome"] != "settled" || result["head"] != head || result["verdict"] != verdict || result["recorded"] != true {
412: 		t.Fatalf("review result = %v; want a recorded %s Verdict for %s", result, verdict, head)
413: 	}
414: 	verdicts := c.verdicts(t)
415: 	last := verdicts[len(verdicts)-1]
416: 	if last.Grant != result["grant"] || last.Head != head || last.Provider != store.GreenhouseReviewProvider || last.Mode != "parallel" || last.Outcome != verdict || last.Blocking != blocking || last.Protocol != "2" || last.Target == "" || last.ReviewBase == "" {
417: 		t.Fatalf("recorded Verdict = %+v; want grant %v head %s %s with %d blocking", last, result["grant"], head, verdict, blocking)
418: 	}
419: 	findings, err := os.ReadFile(last.FindingsPath)
420: 	if err != nil || len(findings) == 0 {
421: 		t.Fatalf("findings file %s: %v", last.FindingsPath, err)
422: 	}
423: }
