150: 				axi.Field{Key: "blocking", Value: verdict.Blocking}, axi.Field{Key: "findings", Value: verdict.FindingsPath}, axi.Field{Key: "recorded", Value: recorded}, axi.Field{Key: "replayed", Value: result.Replayed})
151: 		case greenhouse.Stale:
152: 			refused = append(refused, axi.Object{{Key: "grant", Value: result.Grant}, {Key: "reason", Value: "the head moved during the review"}})
153: 			if err := greenhouse.ClearPending(round.Pending); err != nil {
154: 				return err
155: 			}
156: 			continue
157: 		case greenhouse.RecoveryRequired:
158: 			summary := fmt.Sprintf("%s: Greenhouse review %s of %s parked after an interruption (%s); Posse issues no new grant until it recovers", taskIDString(task.Seq), result.Grant, member.name, result.Recovery.Reason)
159: 			if _, err := db.CreateGreenhouseRecoveryNoticeOnce(ctx.Context, project.ID, task.ID, member.name, result.Recovery.ID, summary); err != nil {
160: 				return err
161: 			}
162: 			output = append(output, axi.Field{Key: "recovery", Value: result.Recovery.ID})
163: 		}
164: 		if len(refused) > 0 {
165: 			output = append(output, axi.Field{Key: "refused", Value: refused})
166: 		}
167: 		return ctx.Print(output)
168: 	}
169: 	return ctx.Print(axi.Object{{Key: "task", Value: taskIDString(task.Seq)}, {Key: "repo", Value: member.name}, {Key: "outcome", Value: string(greenhouse.Stale)}, {Key: "refused", Value: refused}})
