400: func decodeGreenhouseOutput(t *testing.T, output string) map[string]any {
401: 	t.Helper()
402: 	var result map[string]any
403: 	if err := json.Unmarshal([]byte(output), &result); err != nil {
404: 		t.Fatalf("decode review output: %v\n%s", err, output)
405: 	}
406: 	return result
407: }
