463: 	t.Helper()
464: 	c.commit++
465: 	name := fmt.Sprintf("greenhouse-change-%d.txt", c.commit)
466: 	if err := os.WriteFile(filepath.Join(c.change.WorktreePath, name), []byte(fmt.Sprintf("change %d\n", c.commit)), 0o600); err != nil {
