471: 		command.Dir, command.Env = c.change.WorktreePath, c.f.env
472: 		if output, err := command.CombinedOutput(); err != nil {
473: 			t.Fatalf("git %v: %v\n%s", args, err, output)
474: 		}
475: 	}
476: 	command := exec.Command("git", "rev-parse", "HEAD")
477: 	command.Dir, command.Env = c.change.WorktreePath, c.f.env
478: 	head, err := command.Output()
479: 	if err != nil {
480: 		t.Fatal(err)
481: 	}
482: 	return strings.TrimSpace(string(head))
