575: func (c *greenhouseContract) greenhouse(t *testing.T, request map[string]any) map[string]any {
576: 	t.Helper()
577: 	encoded, err := json.Marshal(request)
578: 	if err != nil {
579: 		t.Fatal(err)
580: 	}
581: 	command := exec.Command(filepath.Join(c.f.root, "bin", "greenhouse"), "axi")
582: 	command.Dir = c.change.WorktreePath
583: 	command.Env = setEnv(c.env, "GREENHOUSE_HOME", c.home)
584: 	command.Stdin = strings.NewReader(string(encoded))
585: 	output, err := command.Output()
586: 	if err != nil {
587: 		t.Fatalf("greenhouse axi %s: %v\n%s", encoded, err, output)
588: 	}
589: 	var response map[string]any
590: 	if err := json.Unmarshal(output, &response); err != nil {
591: 		t.Fatalf("greenhouse axi output: %v\n%s", err, output)
592: 	}
593: 	return response
594: }
