285: func (d *Daemon) request(round Round, v response, grant, op string, extra map[string]any) map[string]any {
286: 	q := map[string]any{
287: 		"version": Protocol, "op": op, "host": round.Host,
288: 		"run_id": v.RunID, "input_id": v.InputID, "gate_id": v.GateID, "expected": v.Token,
289: 		"action_id": grant + "/" + op + "/" + v.Token, "reason": "Posse host review " + grant,
290: 	}
291: 	for key, value := range extra {
292: 		q[key] = value
293: 	}
294: 	return q
295: }
