229: 			result = c.review(t)
230: 			return result["outcome"] == "settled"
231: 		}) {
232: 			t.Fatalf("the recovered review did not settle: %v", result)
233: 		}
234: 		c.requireRecorded(t, result, head, "clean", 0)
235: 		if result["grant"] != parked["grant"] || c.invocations(t) != invocations+1 {
236: 			t.Fatalf("recovery spent another grant or reviewer run: %v, invocations %d", result, c.invocations(t))
