211: func greenhouseIntent(task store.Task, plan *taskplan.Plan) string {
212: 	title, doneWhen := task.Title, ""
213: 	if plan != nil {
214: 		for _, input := range plan.Inputs {
215: 			if input.Role != "brief" {
216: 				continue
217: 			}
218: 			if brief, err := dispatch.ParseBriefText(string(input.Bytes)); err == nil {
219: 				if brief.Title != "" {
220: 					title = brief.Title
221: 				}
222: 				doneWhen = brief.DoneWhen
223: 			}
224: 			break
225: 		}
226: 	}
227: 	if doneWhen == "" {
228: 		return title
229: 	}
230: 	return title + "\n\nDone when: " + doneWhen
231: }
